// Walk word, low 3 bits (zero = fully open, so readers that mask &7 and treat non-zero as a wall see at least one side of every wall):
// bit 0 = no body fits anywhere in the cell, bit 1 = east edge blocked, bit 2 = south edge blocked.
// Bits 3-4 / 5-6 = the open lane through the east / south edge (1 centre, 2 at -0.3 m, 3 at +0.3 m) for portal aiming.
fn stepOpen30(wc:u32,wn:u32,d:vec2i,sideA:u32,sideB:u32)->bool {
 if((wn&1u)>0u){return false;}
 if(d.x!=0&&d.y!=0){return (sideA&7u)==0u&&(sideB&7u)==0u&&(wc&6u)==0u&&(wn&6u)==0u;}
 if(d.x==1){return (wc&2u)==0u;}if(d.x==-1){return (wn&2u)==0u;}if(d.y==1){return (wc&4u)==0u;}return (wn&4u)==0u;
}
// The point to aim for when stepping from cell c (centre cp) to the orthogonal neighbour c+d through its open lane.
fn portal30(cp:vec2f,wc:u32,wn:u32,d:vec2i)->vec2f {
